import {collectBlsCalendar,macroCalendarApi} from './macro_calendar.js';
import {collectMacro,trackMacroReactions,linkMacroSignals,macroApi,claimMacroAlerts,ackMacroAlerts} from './macro.js';
import {runCloudflareWatchdog,watchdogStatus,claimWatchdogNotices,ackWatchdogNotices} from './watchdog.js';
import { ingestPublications } from './publications.js';
import { outcomeMetrics,runOutcomeEngine } from './outcomes.js';
import { AtlasLiveRoom, ingestScan, trackingData, claimEvents, ackEvents } from './live.js';
export { AtlasLiveRoom } from './live.js';

const MEXC='https://contract.mexc.com';
const GH='https://raw.githubusercontent.com/DelDeto/Market-Setup-Watch/main/market_hub/';
const headers={'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'};
function json(body,status=200){return new Response(JSON.stringify(body),{status,headers});}
function num(v){if(v===null||v===undefined||v==='')return null;const n=Number(v);return Number.isFinite(n)?n:null;}
async function remote(url,timeout=12000){const control=new AbortController();const t=setTimeout(()=>control.abort(),timeout);try{const r=await fetch(url,{headers:{'accept':'application/json','user-agent':'Crypto-Market-Terminal/1.0'},signal:control.signal});if(!r.ok)throw Error('upstream '+r.status);return await r.json();}finally{clearTimeout(t);}}
function normalise(payload){if(payload?.success===false||!Array.isArray(payload?.data))throw Error('invalid MEXC response');return payload.data.filter(x=>typeof x.symbol==='string'&&x.symbol.endsWith('_USDT')&&num(x.lastPrice)>0).map(x=>({symbol:x.symbol,price:num(x.lastPrice),changePct:num(x.riseFallRate)==null?null:Number(x.riseFallRate)*100,turnover:num(x.amount24),volume:num(x.volume24),high:num(x.high24Price),low:num(x.lower24Price),funding:num(x.fundingRate),updatedAt:new Date().toISOString()})).sort((a,b)=>(b.turnover||0)-(a.turnover||0));}
async function marketFetch(){return normalise(await remote(MEXC+'/api/v1/contract/ticker',11000));}
function parseSignature(str){const p=String(str).split('|');if(p.length<3||!/^[-A-Z0-9_]{3,35}$/.test(p[0]))return null;return {id:'msw:'+p.join('|').slice(0,240),source:'Market Setup Watch',symbol:p[0],bucket:p[1],direction:String(p[2]).toUpperCase(),entryLow:num(p[4]),entryHigh:num(p[5])};}
async function sync(env){
 const attemptedAt=new Date().toISOString();let errors=[];let successes=[];
 await env.DB.prepare("INSERT INTO health(id,last_attempt_at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET last_attempt_at=excluded.last_attempt_at").bind(attemptedAt).run();
 const res=await Promise.allSettled([marketFetch(),remote(GH+'state.json',13000),remote(GH+'calibration.json',13000)]);
 if(res[0].status==='fulfilled'){const rows=res[0].value;await env.DB.prepare("INSERT INTO snapshots(id,fetched_at,source,items_json) VALUES(1,?,'MEXC Futures',?) ON CONFLICT(id) DO UPDATE SET fetched_at=excluded.fetched_at,items_json=excluded.items_json").bind(attemptedAt,JSON.stringify(rows)).run();successes.push('market');}else errors.push('MEXC market: '+String(res[0].reason).slice(0,150));
 if(res[1].status==='fulfilled'){
   const s=res[1].value;const sourceTime=s.updated_at_utc||null;
   if(!Array.isArray(s.signatures))errors.push('scanner state: missing signatures');
   else{
     await env.DB.prepare("INSERT INTO scanner_snapshots(id,source_updated_at,synced_at,counts_json,market_context_json,signatures_json,swing_json) VALUES(1,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET source_updated_at=excluded.source_updated_at,synced_at=excluded.synced_at,counts_json=excluded.counts_json,market_context_json=excluded.market_context_json,signatures_json=excluded.signatures_json,swing_json=excluded.swing_json").bind(sourceTime,attemptedAt,JSON.stringify(s.counts||{}),JSON.stringify(s.market_context||{}),JSON.stringify(s.signatures.slice(0,300)),JSON.stringify(s.swing_top_picks||[])).run();
     const signals=s.signatures.slice(0,80).map(parseSignature).filter(Boolean);
     for(const v of signals){await env.DB.prepare("INSERT INTO signals(id,source,symbol,direction,bucket,entry_low,entry_high,source_updated_at,first_seen_at,last_seen_at) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET last_seen_at=excluded.last_seen_at,source_updated_at=excluded.source_updated_at").bind(v.id,v.source,v.symbol,v.direction,v.bucket,v.entryLow,v.entryHigh,sourceTime,attemptedAt,attemptedAt).run();}
     successes.push('scanner');
   }
 }else errors.push('GitHub scanner: '+String(res[1].reason).slice(0,150));
 if(res[2].status==='fulfilled'){
   const c=res[2].value;await env.DB.prepare("INSERT INTO metrics(id,closed_samples,baseline_win_rate,active,fetched_at) VALUES(1,?,?,?,?) ON CONFLICT(id) DO UPDATE SET closed_samples=excluded.closed_samples,baseline_win_rate=excluded.baseline_win_rate,active=excluded.active,fetched_at=excluded.fetched_at").bind(num(c.closed_samples),num(c.baseline_win_rate),c.active?1:0,attemptedAt).run();successes.push('calibration');
 }else errors.push('GitHub calibration: '+String(res[2].reason).slice(0,150));
 await env.DB.prepare("UPDATE health SET last_success_at=COALESCE(?,last_success_at),last_error=?,synced_sources=? WHERE id=1").bind(successes.length?attemptedAt:null,errors.length?errors.join('; '):null,JSON.stringify(successes)).run();
 return {at:attemptedAt,successes,errors};
}
async function handleMarket(env){try{const rows=await marketFetch();return json({source:'MEXC Futures',mode:'live-on-request',updatedAt:new Date().toISOString(),items:rows});}catch(e){const r=await env.DB.prepare('SELECT * FROM snapshots WHERE id=1').first();return json({source:r?.source||'MEXC Futures',mode:'last-snapshot',updatedAt:r?.fetched_at||null,items:r?JSON.parse(r.items_json):[],warning:'Live API unavailable; showing last successful snapshot',error:String(e).slice(0,130)},r?200:503);}}
async function handleDashboard(env){const [s,m,h,history]=await Promise.all([env.DB.prepare('SELECT * FROM scanner_snapshots WHERE id=1').first(),env.DB.prepare('SELECT * FROM metrics WHERE id=1').first(),env.DB.prepare('SELECT * FROM health WHERE id=1').first(),env.DB.prepare('SELECT * FROM signals ORDER BY last_seen_at DESC LIMIT 120').all()]);return json({scanner:s?{updatedAt:s.source_updated_at,syncedAt:s.synced_at,counts:JSON.parse(s.counts_json),marketContext:JSON.parse(s.market_context_json||'{}'),swing:JSON.parse(s.swing_json||'[]')}:null,calibration:m?{closedSamples:m.closed_samples,baselineWinRate:m.baseline_win_rate,active:!!m.active,updatedAt:m.fetched_at}:null,health:h||null,signals:history.results||[],notes:'Scanner signatures are last published alert snapshots, not independently verified open positions. Calibration is historical and is not realized PnL.'});}
async function handleChart(url){const symbol=url.searchParams.get('symbol')||'BTC_USDT';if(!/^[A-Z0-9]{2,25}_USDT$/.test(symbol))return json({error:'invalid symbol'},400);const period=url.searchParams.get('tf')==='1h'?'Min60':'Min15';const now=Math.floor(Date.now()/1000);const seconds=period==='Min60'?3600:900;const from=now-seconds*105;try{const data=await remote(MEXC+'/api/v1/contract/kline/'+symbol+'?interval='+period+'&start='+from+'&end='+now,10000);const d=data?.data;if(!d||!Array.isArray(d.time))throw Error('missing candles');const rows=d.time.map((t,i)=>({t:Number(t)*1000,o:num(d.open?.[i]),h:num(d.high?.[i]),l:num(d.low?.[i]),c:num(d.close?.[i])})).filter(x=>x.c>0&&x.t<Math.floor(now/seconds)*seconds*1000).slice(-90);return json({symbol,tf:period,candles:rows});}catch(e){return json({symbol,candles:[],error:'Chart source unavailable: '+String(e).slice(0,90)},503);}}
async function handleIngest(req,env){if(!env.PUBLISH_TOKEN)return json({error:'Webhook not configured; required PUBLISH_TOKEN secret'},503);const auth=req.headers.get('authorization')||'';if(auth!=='Bearer '+env.PUBLISH_TOKEN)return json({error:'unauthorized'},401);let x;try{x=await req.json()}catch{return json({error:'invalid JSON'},400)}if(!x||!/^[-A-Z0-9_]{3,35}$/.test(x.symbol||'')||!['LONG','SHORT'].includes(x.direction)||!['ENTRY_READY','NEAR_ENTRY','DEVELOPING','WATCHLIST','EXPIRED','TP','SL'].includes(x.bucket)||typeof x.source!=='string')return json({error:'invalid signal fields'},400);const at=new Date().toISOString();const id=String(x.id||x.source+':'+x.symbol+':'+x.direction+':'+at).slice(0,240);await env.DB.prepare("INSERT INTO signals(id,source,symbol,direction,bucket,entry_low,entry_high,source_updated_at,first_seen_at,last_seen_at) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET bucket=excluded.bucket,entry_low=excluded.entry_low,entry_high=excluded.entry_high,last_seen_at=excluded.last_seen_at").bind(id,x.source.slice(0,80),x.symbol,x.direction,x.bucket,num(x.entry_low),num(x.entry_high),at,at,at).run();return json({ok:true,id});}

async function syncResearch(env){
 const last=await env.DB.prepare("SELECT MAX(imported_at) AS t FROM research_sources").first();
 if(last?.t&&Date.now()-Date.parse(last.t)<50*60*1000)return {skipped:true};
 const sources=[
 ['Crypto Short M2','https://raw.githubusercontent.com/DelDeto/Crypto_Short/main/state/m2_live_signals.json'],
 ['Crypto Short M3','https://raw.githubusercontent.com/DelDeto/Crypto_Short/main/state/m3_v32_signals.json'],
 ['VVV Trading AI','https://raw.githubusercontent.com/DelDeto/vvv-trading-ai/main/signal_history.json']
 ];
 const r=await Promise.allSettled(sources.map(x=>remote(x[1],14000)));
 const results=[];
 for(let i=0;i<sources.length;i++){
  const source=sources[i][0],at=new Date().toISOString();
  if(r[i].status!=='fulfilled'){results.push({source,error:String(r[i].reason)});continue;}
  const d=r[i].value,all=Array.isArray(d.signals)?d.signals:[],records=all.slice(-70),sourceTime=d.updated_at||d.updated_at_utc||null;
  let closed=0,netSum=0;
  for(const v of records){
   const outcome=String(v.outcome_state||v.outcome||'').toUpperCase();
   const status=String(v.outcome_status||'').toUpperCase();
   const net=num(v.net_r);
   if(status==='CLOSED'||(outcome&&outcome!=='OPEN')){closed++;if(net!==null)netSum+=net;}
   const id=(source+':'+String(v.signal_id||v.id||v.signature||v.generated_at_utc||v.signal_time||Math.random())).slice(0,240);
   const entry=num(v.entry??v.entry_reference??v.entry_mid??v.entry_zone?.lower);
   const stop=num(v.stop??v.invalidation??v.stop_loss);
   const tp1=num(v.tp1??v.targets?.[0]?.price);
   const time=v.recorded_at||v.generated_at_utc||v.signal_time||v.entry_time||sourceTime||null;
   await env.DB.prepare("INSERT INTO research_signals(id,source,model,symbol,direction,recorded_at,outcome_status,outcome,entry,stop,tp1,net_r,detail_json,imported_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET outcome_status=excluded.outcome_status,outcome=excluded.outcome,net_r=excluded.net_r,detail_json=excluded.detail_json,imported_at=excluded.imported_at").bind(id,source,String(v.model||'').slice(0,70),source==='VVV Trading AI'?'VVV_USDT':String(v.symbol||'UNKNOWN').slice(0,35),String(v.direction||(source==='VVV Trading AI'?'SHORT':'SHORT')).toUpperCase(),time,status,outcome,entry,stop,tp1,net,JSON.stringify(v).slice(0,8500),at).run();
  }
  await env.DB.prepare("INSERT INTO research_sources(source,updated_at,imported_at,total_signals,imported_signals,closed_signals,net_r_sum,last_error) VALUES(?,?,?,?,?,?,?,NULL) ON CONFLICT(source) DO UPDATE SET updated_at=excluded.updated_at,imported_at=excluded.imported_at,total_signals=excluded.total_signals,imported_signals=excluded.imported_signals,closed_signals=excluded.closed_signals,net_r_sum=excluded.net_r_sum,last_error=NULL").bind(source,sourceTime,at,all.length,records.length,closed,netSum).run();
  results.push({source,imported:records.length,sourceTime});
 }
 return results;
}
async function handleResearch(env){
 const [rows,sources]=await Promise.all([env.DB.prepare("SELECT id,source,model,symbol,direction,recorded_at,outcome_status,outcome,entry,stop,tp1,net_r FROM research_signals ORDER BY recorded_at DESC LIMIT 180").all(),env.DB.prepare("SELECT * FROM research_sources ORDER BY source").all()]);
 return json({signals:rows.results||[],sources:sources.results||[],note:"Research journal is a historical import of GitHub files. OPEN in old source data is not proof of a currently open position. Net R is as recorded by its respective model, not consolidated account PnL."});
}

export default {
 async fetch(req,env){const url=new URL(req.url);try{
  if(req.method==='GET'&&url.pathname==='/')return new Response(HTML,{headers:{'content-type':'text/html;charset=utf-8','cache-control':'public,max-age=60','content-security-policy':"default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; connect-src 'self' wss://atlas-market-terminal.duc-nguyen-ndd127.workers.dev wss://atlas-terminal-v2-preview.duc-nguyen-ndd127.workers.dev; img-src 'self' data:; frame-ancestors 'none'",'x-frame-options':'DENY','x-content-type-options':'nosniff'}});
  if(req.method==='GET'&&url.pathname==='/api/ws'){return env.LIVE_ROOM.get(env.LIVE_ROOM.idFromName('atlas-usdt-futures')).fetch(req);}
  if(req.method==='GET'&&url.pathname==='/api/live-health')return env.LIVE_ROOM.get(env.LIVE_ROOM.idFromName('atlas-usdt-futures')).fetch('https://room.internal/status');
  if(req.method==='GET'&&url.pathname==='/api/tracking')return trackingData(env);
  if(req.method==='GET'&&url.pathname==='/api/outcomes')return outcomeMetrics(env);
  if(req.method==='GET'&&url.pathname==='/api/macro')return macroApi(env,url);
  if(req.method==='GET'&&url.pathname==='/api/macro/calendar')return macroCalendarApi(env);
  if(req.method==='POST'&&url.pathname==='/api/macro/alerts/claim')return claimMacroAlerts(req,env);
  if(req.method==='POST'&&url.pathname==='/api/macro/alerts/ack')return ackMacroAlerts(req,env);
  if(req.method==='GET'&&url.pathname==='/api/watchdog')return watchdogStatus(env);
  if(req.method==='POST'&&url.pathname==='/api/watchdog/claim')return claimWatchdogNotices(req,env);
  if(req.method==='POST'&&url.pathname==='/api/watchdog/ack')return ackWatchdogNotices(req,env);
  if(req.method==='POST'&&url.pathname==='/api/ingest/github')return ingestPublications(req,env);
  if(req.method==='POST'&&url.pathname==='/api/alerts/claim')return claimEvents(req,env);
  if(req.method==='POST'&&url.pathname==='/api/alerts/ack')return ackEvents(req,env);
  if(req.method==='GET'&&url.pathname==='/api/market')return handleMarket(env);
  if(req.method==='GET'&&url.pathname==='/api/dashboard')return handleDashboard(env);
  if(req.method==='GET'&&url.pathname==='/api/research')return handleResearch(env);
  if(req.method==='GET'&&url.pathname==='/api/chart')return handleChart(url);
  if(req.method==='GET'&&url.pathname==='/api/health'){const r=await env.DB.prepare('SELECT * FROM health WHERE id=1').first();const age=r?.last_success_at?(Date.now()-Date.parse(r.last_success_at))/60000:null;return json({status:age===null?'not-initialized':age>15?'stale':'ok',lastSuccess:r?.last_success_at||null,lastAttempt:r?.last_attempt_at||null,lastError:r?.last_error||null,ageMinutes:age});}
  if(req.method==='POST'&&url.pathname==='/api/ingest')return handleIngest(req,env);
  return json({error:'not found'},404);
 }catch(e){return json({error:'Service failure',detail:String(e).slice(0,180)},500);}},
 async scheduled(evt,env,ctx){ctx.waitUntil((async()=>{
  if(evt.cron==='*/3 * * * *'){
   try{const report=await runCloudflareWatchdog(env);if(report.status!=='OK')console.warn('Independent watchdog',report.status,report.note)}
   catch(e){console.error('Independent watchdog failed:',String(e))}
   return;
  }
  if(evt.cron==='*/5 * * * *'){
   try{await sync(env)}catch(e){console.error('Terminal source sync failure:',String(e))}
   try{await syncResearch(env)}catch(e){console.error('Research sync:',String(e))}
   // Independent macro ingestion; news failures must not interrupt scanner or market sync.
   try{const news=await collectMacro(env);if(news.errors.length)console.warn('Macro partial sources',news.errors.join(' | '))}catch(e){console.error('Macro collector:',String(e))}
   try{const calendar=await collectBlsCalendar(env);if(calendar.error)console.warn('BLS economic calendar',calendar.error)}catch(e){console.error('Calendar collector:',String(e))}
   try{const reaction=await trackMacroReactions(env,{max:8});if(reaction.errors.length)console.warn('Macro reaction gaps',reaction.errors.join(' | '))}catch(e){console.error('Macro reactions:',String(e))}
   try{await linkMacroSignals(env)}catch(e){console.error('Macro-signal context:',String(e))}
   try{const room=env.LIVE_ROOM.get(env.LIVE_ROOM.idFromName('atlas-usdt-futures'));await room.fetch('https://room.internal/wake',{method:'POST'})}catch(e){console.error('Live hub wake:',String(e))}
   return;
  }
  if(evt.cron==='*/2 * * * *'){
   try{const result=await runOutcomeEngine(env,{limit:18});if(result.errors.length)console.error('Outcome scan partial:',result.errors.join('; '))}
   catch(e){console.error('Outcome engine failure:',String(e))}
  }
 })());}
};
const HTML="<!doctype html>\n<html lang=\"vi\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#0b1020\"><title>ATLAS Terminal — Crypto Market Intelligence</title>\n<style>\n:root{color-scheme:dark;--bg:#090d17;--surface:#101726;--panel:#151e30;--line:#273248;--muted:#8292b1;--text:#ebf2ff;--green:#30daa5;--red:#fa6c86;--blue:#5f9fff}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui,-apple-system,Segoe UI,sans-serif}button,input,select{font:inherit;color:inherit}button{cursor:pointer}.shell{display:grid;grid-template-columns:224px minmax(0,1fr);min-height:100vh}.sidebar{background:#0c1322;border-right:1px solid var(--line);padding:28px 17px;position:sticky;top:0;height:100vh}.brand{display:flex;gap:11px;align-items:center;padding:0 9px 31px;font-weight:800;letter-spacing:.7px;font-size:17px}.logo{display:grid;place-items:center;width:36px;height:36px;background:linear-gradient(140deg,#556bf4,#12c7ae);border-radius:11px;font-size:24px}.brand small{display:block;font-size:9px;color:var(--muted);letter-spacing:1.6px;font-weight:600;margin-top:4px}.nav{display:grid;gap:6px}.nav button{border:0;background:transparent;text-align:left;color:#9aa9c5;padding:13px;border-radius:9px}.nav button.active,.nav button:hover{color:#fff;background:#1d2941}.asidefoot{position:absolute;bottom:23px;left:25px;right:20px;color:#7284a6;font-size:11px;line-height:1.8}.main{min-width:0;padding:27px 32px;max-width:1700px;width:100%;margin:0 auto}.top{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:25px}.eyebrow{text-transform:uppercase;letter-spacing:2.1px;color:#7f94ba;font-size:10px;font-weight:700}.top h1{font-size:27px;margin:5px 0 0;letter-spacing:-.7px}.live{display:flex;align-items:center;gap:8px;padding:9px 13px;border:1px solid #22483c;border-radius:100px;background:#10291f;color:#60edbd;font-size:12px;font-weight:700}.dot{width:7px;height:7px;background:currentColor;border-radius:50%;box-shadow:0 0 10px currentColor}.warn{color:#f9bf6d;border-color:#56412d;background:#2b2118}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:17px}.stat{background:linear-gradient(140deg,#161f31,#101726);border:1px solid var(--line);border-radius:13px;padding:17px 20px}.stat .k{color:#92a2bc;font-size:12px}.stat .v{font-size:27px;font-weight:750;margin-top:13px;font-variant-numeric:tabular-nums}.stat .s{font-size:11px;color:#7287a8;margin-top:8px}.up{color:var(--green)}.down{color:var(--red)}.panel{background:var(--surface);border:1px solid var(--line);border-radius:14px;min-width:0;overflow:hidden}.panelhead{padding:17px 19px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:10px}.panelhead h2{font-size:15px;margin:0}.small{font-size:11px;color:var(--muted)}.layout{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(300px,1fr);gap:16px}.tools{display:flex;gap:8px;align-items:center}.tools input,.tools select{background:#0b1220;border:1px solid var(--line);border-radius:7px;padding:9px 10px;max-width:160px;outline:none}.tools input:focus{border-color:var(--blue)}.scroll{overflow:auto;max-height:545px}table{border-collapse:collapse;width:100%;white-space:nowrap;font-size:12px}thead{position:sticky;top:0;background:#172033;color:#94a4be}th{text-align:left;font-weight:650;padding:13px 14px}td{padding:13px 14px;border-top:1px solid #202a3d;font-variant-numeric:tabular-nums}tr:hover td{background:#1a2540;cursor:pointer}.sym{font-weight:750;color:#f0f5ff}.muted{color:var(--muted)}.tag{display:inline-block;border-radius:5px;background:#29344b;padding:4px 6px;font-size:10px;color:#b2c5e8}.tag.ready{background:#173e37;color:#62e5bf}.tag.dev{background:#3d3121;color:#f8cc7b}.chartbody{padding:16px}.canvas{width:100%;height:265px;display:block}.symbolbar{display:flex;align-items:center;justify-content:space-between}.symbolbar strong{font-size:18px}.mini{display:flex;gap:5px}.mini button{border:1px solid var(--line);border-radius:6px;background:#111b2b;padding:6px 10px;color:#9baac8}.mini button.active{background:#254872;color:white}.note{padding:11px 16px;border-top:1px solid var(--line);font-size:11px;line-height:1.5;color:#8093b1}.signals{margin-top:16px}.empty{padding:35px 14px;text-align:center;color:var(--muted)}.notice{color:#b8cae3;font-size:12px;line-height:1.7;padding:18px;border-radius:10px;border:1px solid var(--line);margin-top:15px;background:#111b2c}.analytics{display:none;grid-template-columns:1fr 1fr;gap:16px}.analytics .stat{min-height:125px}.bargrid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding:20px}.metric{text-align:center;background:#17233a;border:1px solid #2a3b52;padding:19px 5px;border-radius:9px}.metric b{font-size:24px;display:block}.metric small{color:#9aaaca;font-size:10px}.status{padding:20px;color:#b5c8dc;line-height:1.9}.hide{display:none!important}\n@media(max-width:1100px){.layout{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:720px){.shell{display:block}.sidebar{height:auto;position:static;padding:11px 13px}.brand{padding:0 0 9px}.nav{display:flex;overflow:auto}.nav button{white-space:nowrap;padding:8px 12px}.asidefoot{display:none}.main{padding:19px 13px}.top h1{font-size:22px}.stats{gap:8px}.stat{padding:13px}.stat .v{font-size:20px}.tools input{width:95px}.analytics{grid-template-columns:1fr}}\n\n.macro-controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:0 16px 16px}\n.macro-controls input,.macro-controls select,.macro-controls button{background:#101b2b;border:1px solid #34425c;border-radius:10px;color:#f0f4ff;padding:10px 12px}\n.macro-controls input{flex:1;min-width:180px}\n.macro-controls button{cursor:pointer;font-weight:700}\n.macro-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,355px),1fr));gap:12px;padding:0 16px 16px}\n.macro-card{border:1px solid #293c54;border-radius:15px;padding:16px;background:linear-gradient(155deg,#162337,#111a2b);display:flex;flex-direction:column;gap:10px}\n.macro-top{display:flex;justify-content:space-between;align-items:center;gap:9px;flex-wrap:wrap}\n.macro-kicker{font-size:11px;letter-spacing:.08em;color:#a7bedf;font-weight:700}\n.macro-title{font-size:15px;line-height:1.55;font-weight:700;color:#eef4ff}\n.macro-summary{font-size:13px;line-height:1.65;color:#d2deed}\n.macro-impact{font-size:12px;line-height:1.6;color:#a7bdd8;padding:10px;border-radius:9px;background:#0b1725}\n.macro-tags{display:flex;gap:6px;align-items:center;flex-wrap:wrap}\n.macro-tag{font-size:10px;font-weight:750;border:1px solid #415574;border-radius:50px;padding:4px 8px;color:#c5d5e7}\n.macro-tag.high{color:#ffabb0;border-color:#a05a63;background:#422632}\n.macro-tag.medium{color:#f0d58b;border-color:#8b754b}\n.macro-tag.good{color:#8fdbb8;border-color:#2e8669}\n.macro-card a{color:#8fc4ff;font-size:12px;text-decoration:none}\n.macro-reaction{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}\n.macro-asset{border:1px solid #28394e;border-radius:8px;padding:8px;background:#0d1828;font-size:11px;color:#b9d0ea}\n.macro-asset strong{font-size:13px}\n.macro-up{color:#7be6b5}.macro-down{color:#ff989c}\n\n.top-actions{display:flex;gap:11px;align-items:center;flex-wrap:wrap;justify-content:flex-end}\n.timezone-control{display:flex;flex-direction:column;gap:5px;color:#95afd3;font-size:10px;font-weight:750;letter-spacing:.07em}\n.timezone-control select{background:#142036;color:#ebf2ff;border:1px solid #344764;border-radius:10px;padding:9px 32px 9px 11px;max-width:200px;font-weight:700;font-size:12px;cursor:pointer}\n.timezone-control select:focus-visible{outline:2px solid #5f9fff;outline-offset:2px}\n@media(max-width:720px){.top{align-items:flex-start;flex-wrap:wrap}.top-actions{width:100%;justify-content:space-between}.timezone-control select{max-width:180px}}\n</style></head><body>\n<div class=\"shell\">\n<aside class=\"sidebar\"><div class=\"brand\"><div class=\"logo\">⌁</div><div>ATLAS <span style=\"color:#5da5ff\">TERMINAL</span><small>MARKET INTELLIGENCE</small></div></div><div class=\"nav\"><button class=\"active\" data-tab=\"market\">◈ &nbsp; Market Terminal</button><button data-tab=\"signals\">◉ &nbsp; Signal Feed</button><button data-tab=\"tracking\">⚡ &nbsp; Live Signal Tracking</button><button data-tab=\"macro\">◈ &nbsp; Macro & News</button><button data-tab=\"research\">⌕ &nbsp; Research Journal</button><button data-tab=\"analytics\">▤ &nbsp; Performance & Health</button></div><div class=\"asidefoot\">MEXC Perpetual Futures<br>Market data: public APIs<br>Trading: manual only · No auto-orders<br><span id=\"clock\"></span></div></aside>\n<main class=\"main\"><div class=\"top\"><div><div class=\"eyebrow\">24 / 7 MARKET OBSERVATION</div><h1 id=\"heading\">Market Intelligence Overview</h1></div><div class=\"top-actions\"><label class=\"timezone-control\" for=\"timezoneSelect\"><span>TIME ZONE</span><select id=\"timezoneSelect\" aria-label=\"Múi giờ hiển thị\"><option value=\"VN\">Việt Nam · UTC+7</option><option value=\"UTC\">UTC · UTC+0</option></select></label><div class=\"live warn\" id=\"indicator\"><span class=\"dot\"></span><span id=\"indicatorText\">Connecting</span></div></div></div>\n<div class=\"stats\"><div class=\"stat\"><div class=\"k\">Tracked instruments</div><div class=\"v\" id=\"count\">—</div><div class=\"s\">MEXC USDT Perpetual · full available market</div></div><div class=\"stat\"><div class=\"k\">ENTRY_READY (scanner)</div><div class=\"v up\" id=\"ready\">—</div><div class=\"s\">Latest published scanner state</div></div><div class=\"stat\"><div class=\"k\">Developing / near entry</div><div class=\"v\" id=\"developing\">—</div><div class=\"s\">Setup candidates, not filled trades</div></div><div class=\"stat\"><div class=\"k\">Last scanner run (<span class=\"tzlabel\">ICT (UTC+7)</span>)</div><div class=\"v\" id=\"lastscan\" style=\"font-size:18px\">—</div><div class=\"s\" id=\"syncAge\">Waiting for synchronization</div></div></div>\n<section id=\"marketTab\"><div class=\"layout\">\n<div class=\"panel\"><div class=\"panelhead\"><div><h2>Live Market Scanner</h2><div class=\"small\" id=\"markettime\">Market API · reconnectable server push</div></div><div class=\"tools\"><input id=\"search\" placeholder=\"Search symbol...\"><select id=\"direction\"><option value=\"all\">All markets</option><option value=\"up\">Gainers</option><option value=\"down\">Losers</option></select></div></div><div class=\"scroll\"><table><thead><tr><th>Instrument</th><th>Last price</th><th>24h %</th><th>Turnover 24h</th><th>Funding</th></tr></thead><tbody id=\"marketrows\"><tr><td colspan=\"5\" class=\"empty\">Connecting to market API...</td></tr></tbody></table></div><div class=\"note\">Browser receives WebSocket pushes when connected (typically every ~10 seconds). Source is exchange REST snapshots, NOT individual exchange trade ticks. Server checks every ~30 seconds with no connected viewers.</div></div>\n<div class=\"panel\"><div class=\"panelhead\"><h2>Price Action</h2><span class=\"small\" id=\"chartstatus\">Closed candles</span></div><div class=\"chartbody\"><div class=\"symbolbar\"><strong id=\"chartsymbol\">BTC_USDT</strong><div class=\"mini\"><button id=\"tf15\" class=\"active\">15m</button><button id=\"tf1h\">1h</button></div></div><canvas class=\"canvas\" id=\"chart\"></canvas><div class=\"small\" id=\"chartnote\">Loading MEXC candles...</div></div><div class=\"note\">OHLCV visualization · last closed candles only. This is not an execution interface.</div></div>\n</div></section>\n<section id=\"signalsTab\" class=\"hide\"><div class=\"panel\"><div class=\"panelhead\"><h2>Scanner Alert History</h2><span class=\"small\">Published signatures from Market-Setup-Watch</span></div><div class=\"scroll\" style=\"max-height:700px\"><table><thead><tr><th>Market</th><th>Direction</th><th>Scanner status</th><th>Entry zone (if supplied)</th><th>Source timestamp</th></tr></thead><tbody id=\"signalrows\"><tr><td colspan=\"5\" class=\"empty\">Synchronizing scanner...</td></tr></tbody></table></div></div><div class=\"notice\">These records come from the scanner's last published alert signatures. A signature does not prove that a trade was entered, is still active, or reached TP/SL. Confirm conditions using your existing scanner and chart before acting.</div></section>\n<section id=\"trackingTab\" class=\"hide\"><div class=\"stats\" id=\"outcomeStats\"><div class=\"stat\"><div class=\"k\">Telegram publications journaled</div><div class=\"v\" id=\"pubcount\">—</div><div class=\"s\">Confirmed source messages; history starts at V3</div></div><div class=\"stat\"><div class=\"k\">Tracked READY/SWING plans</div><div class=\"v\" id=\"moncount\">—</div><div class=\"s\">Plans with valid Entry/SL/TP</div></div><div class=\"stat\"><div class=\"k\">TP1 first / SL first</div><div class=\"v\" id=\"resolved\">—</div><div class=\"s\">Only non-ambiguous closed-candle outcomes</div></div><div class=\"stat\"><div class=\"k\">TP1-first rate (observations)</div><div class=\"v\" id=\"outcomeRate\">—</div><div class=\"s\">Not verified portfolio win rate</div></div></div><div class=\"notice\" id=\"outcomeHealthNote\">Outcome engine: awaiting first closed-candle evaluation</div>\n<div class=\"panel\"><div class=\"panelhead\"><div><h2>Live Price-Observation Tracker</h2><div class=\"small\">Verified Market-Setup-Watch plans · observation only</div></div><span class=\"small\" id=\"liveTrackerSummary\">Waiting for published plans</span></div>\n<div class=\"scroll\" style=\"max-height:610px\"><table><thead><tr><th>Symbol</th><th>Side / Score</th><th>Observed state</th><th>Entry range</th><th>Stop</th><th>TP1 / TP2</th><th>Latest sampled price</th><th>Last observation</th></tr></thead><tbody id=\"trackerows\"><tr><td colspan=\"8\" class=\"empty\">No verified live plans yet. Waiting for the next scheduled scanner run.</td></tr></tbody></table></div></div>\n<div class=\"panel\" style=\"margin-top:16px\"><div class=\"panelhead\"><h2>Confirmed Telegram Publications</h2><span class=\"small\" id=\"pubsummary\">Audited notification ledger</span></div><div class=\"scroll\" style=\"max-height:360px\"><table><thead><tr><th>Sent at <span class=\"tzlabel\">ICT (UTC+7)</span></th><th>Symbol</th><th>Direction</th><th>Source bucket</th><th>Outcome monitoring</th></tr></thead><tbody id=\"pubrows\"><tr><td colspan=\"5\" class=\"empty\">No verified Telegram publications imported yet.</td></tr></tbody></table></div></div><div class=\"panel\" style=\"margin-top:16px\"><div class=\"panelhead\"><h2>Price-observation events</h2><span class=\"small\" id=\"eventsummary\">Recorded event journal</span></div>\n<div class=\"scroll\" style=\"max-height:360px\"><table><thead><tr><th>Observation</th><th>Instrument</th><th>Sampled price</th><th>Timestamp (<span class=\"tzlabel\">ICT (UTC+7)</span>)</th><th>Telegram relay</th></tr></thead><tbody id=\"eventrows\"><tr><td colspan=\"5\" class=\"empty\">No event history.</td></tr></tbody></table></div></div>\n<div class=\"notice\">Tracking outcomes now use chronological MEXC closed candles (1-minute intraday / 15-minute swing) and explicitly mark same-candle ambiguities and missing candle history. They are theoretical price-level observations, not evidence of order fills, actual PnL or exchange tick-by-tick chronology.</div>\n</section><section id=\"macroTab\" class=\"hide\">\n<div class=\"stats macro-stats\">\n <div class=\"stat\"><div class=\"k\">MACRO FEED</div><div class=\"v\" id=\"macroCount\">—</div><div class=\"s\">Sourced articles, not trade signals</div></div>\n <div class=\"stat\"><div class=\"k\">HIGH IMPACT</div><div class=\"v\" id=\"macroHigh\">—</div><div class=\"s\">In visible news timeline</div></div>\n <div class=\"stat\"><div class=\"k\">SOURCE HEALTH</div><div class=\"v\" id=\"macroSources\">—</div><div class=\"s\">Feeds successfully checked</div></div>\n <div class=\"stat\"><div class=\"k\">BTC / ETH REACTION</div><div class=\"v\" id=\"macroReactions\">—</div><div class=\"s\">Recorded price windows, not causation</div></div>\n</div>\n<div class=\"notice\">V3.5 · News-based scenarios are conditional and are not trading advice. No consensus/forecast values are invented. BTC/ETH reaction windows are observed returns, <b>not evidence news caused the move</b>. Market scanner Entry/SL/TP plans remain unchanged.</div>\n<div class=\"panel\" style=\"margin-top:16px\"><div class=\"panelhead\"><div><h2>UPCOMING ECONOMIC RELEASES</h2><div class=\"small\">Official US BLS calendar · CPI · Employment / NFP · PPI · JOLTS · ECI</div></div><span class=\"small\" id=\"macroCalendarStatus\">Awaiting official iCal feed</span></div>\n<div class=\"notice\">Upcoming scheduled events only. All displayed times use the time zone selected above (Việt Nam UTC+7 by default, or UTC). Forecast, actual and surprise numbers are not supplied by BLS iCal and are not invented. Official schedule may change.</div>\n<div class=\"scroll\" style=\"max-height:400px\"><table><thead><tr><th>Scheduled</th><th>Release</th><th>Impact</th><th>Source</th></tr></thead><tbody id=\"macroCalendarRows\"><tr><td colspan=\"4\" class=\"empty\">Waiting for verified BLS calendar data.</td></tr></tbody></table></div></div><div class=\"panel\" style=\"margin-top:16px\"><div class=\"panelhead\"><div><h2>MACRO & NEWS INTELLIGENCE</h2><div class=\"small\">Official Fed / BLS / SEC / ECB · Secondary crypto publishers clearly identified · English source / Vietnamese context</div></div><span class=\"small\" id=\"macroStatus\">Collector initialization</span></div>\n <div class=\"macro-controls\"><select id=\"macroImpactFilter\" aria-label=\"Impact filter\"><option value=\"\">All impact</option><option value=\"HIGH\">High impact</option><option value=\"MEDIUM\">Medium impact</option><option value=\"LOW\">Low impact</option></select><input id=\"macroSearch\" placeholder=\"Search news or ticker...\" aria-label=\"Search macro articles\"/><button id=\"macroRefresh\" type=\"button\">↻ Refresh</button></div>\n <div id=\"macroNews\" class=\"macro-grid\"><div class=\"empty\">Awaiting verified RSS items from Cloudflare Cron...</div></div>\n</div>\n<div class=\"panel\" style=\"margin-top:16px\"><div class=\"panelhead\"><div><h2>MACRO × SIGNAL CONTEXT</h2><div class=\"small\">Potential alignment, conflict or unknown; not an execution filter</div></div><span class=\"small\" id=\"macroContextCount\">—</span></div><div class=\"scroll\" style=\"max-height:350px\"><table><thead><tr><th>Signal</th><th>Published</th><th>Macro article</th><th>Interpretation</th></tr></thead><tbody id=\"macroContextRows\"><tr><td colspan=\"4\" class=\"empty\">No high-impact macro context linked yet.</td></tr></tbody></table></div></div>\n<div class=\"panel\" style=\"margin-top:16px\"><div class=\"panelhead\"><h2>Source and freshness audit</h2><span class=\"small\">No feed is guaranteed to be real-time</span></div><div class=\"scroll\"><table><thead><tr><th>Source</th><th>Tier</th><th>Last success</th><th>New</th><th>Issue</th></tr></thead><tbody id=\"macroFeeds\"><tr><td colspan=\"5\" class=\"empty\">Waiting for first scheduled import</td></tr></tbody></table></div></div>\n</section><section id=\"researchTab\" class=\"hide\"><div class=\"panel\"><div class=\"panelhead\"><div><h2>Historical Research Signals</h2><div class=\"small\">Imported from Crypto Short M2 / M3 and VVV Trading AI</div></div><span class=\"small\" id=\"researchStatus\">Waiting for first research sync</span></div><div class=\"scroll\" style=\"max-height:660px\"><table><thead><tr><th>Source / Model</th><th>Symbol</th><th>Direction</th><th>Source status</th><th>Reference entry</th><th>Recorded net R</th><th>Source date</th></tr></thead><tbody id=\"researchRows\"><tr><td colspan=\"7\" class=\"empty\">Waiting for scheduled import...</td></tr></tbody></table></div></div><div class=\"notice\">Historical research records can be weeks old. Source status OPEN may be stale. These are research observations, not verified positions or trade recommendations. Different models use different exit assumptions; do not aggregate results as a single account PnL.</div></section><section id=\"analyticsTab\" class=\"hide\"><div class=\"analytics\" id=\"analyticsBox\"><div class=\"stat\"><div class=\"k\">Calibration historical samples</div><div class=\"v\" id=\"samples\">—</div><div class=\"s\">Historical closed samples in source calibration</div></div><div class=\"stat\"><div class=\"k\">Historical calibration win rate</div><div class=\"v\" id=\"winrate\">—</div><div class=\"s\">Not a live portfolio win rate</div></div><div class=\"panel\"><div class=\"panelhead\"><h2>Scanner buckets</h2></div><div class=\"bargrid\"><div class=\"metric\"><b id=\"b1\">—</b><small>READY</small></div><div class=\"metric\"><b id=\"b2\">—</b><small>NEAR</small></div><div class=\"metric\"><b id=\"b3\">—</b><small>DEV</small></div><div class=\"metric\"><b id=\"b4\">—</b><small>WATCH</small></div></div></div><div class=\"panel\"><div class=\"panelhead\"><h2>Service health</h2></div><div class=\"status\" id=\"serviceHealth\">Waiting for first scheduled sync.</div></div><div class=\"panel\"><div class=\"panelhead\"><h2>Independent Cloudflare Watchdog V3.1</h2><span class=\"small\">Cron every 3 min</span></div><div class=\"status\" id=\"watchdogHealth\">Checking scanner freshness...</div></div></div><div class=\"notice\">Historical calibration comes from the source scanner and should not be interpreted as forward-tested profitability, actual fills, or realized PnL. Automated execution is intentionally disabled.</div></section>\n<div class=\"notice\" id=\"systemNotice\">Loading... Data availability depends on the public exchange API and GitHub scanner state. Timestamps are displayed in the selected time zone (default: Việt Nam UTC+7); server-side timestamps remain UTC for calculation.</div>\n</main></div>\n<script>\nvar state={markets:[],dashboard:null,symbol:'BTC_USDT',tf:'15m',tab:'market',zone:'VN'};\nfunction $(id){return document.getElementById(id)}\nfunction esc(s){return String(s==null?'':s).replace(/[&<>\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]})}\nfunction fmt(n,d){return Number.isFinite(Number(n))?Number(n).toLocaleString('en-US',{maximumFractionDigits:d||0}):'—'}\nfunction price(n){return !Number.isFinite(Number(n))?'—':Number(n)<.01?Number(n).toPrecision(5):Number(n)<1?fmt(n,5):fmt(n,2)}\nfunction formatStamp(t){\n if(t===null||t===undefined||t==='')return '—';\n const d=new Date(t);\n if(!Number.isFinite(d.getTime()))return '—';\n const tz=state.zone==='UTC'?'UTC':'Asia/Ho_Chi_Minh';\n const list=new Intl.DateTimeFormat('en-GB',{timeZone:tz,hourCycle:'h23',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'}).formatToParts(d);\n const val=name=>list.find(p=>p.type===name)?.value||'00';\n return val('day')+'/'+val('month')+'/'+val('year')+' '+val('hour')+':'+val('minute')+':'+val('second')+(state.zone==='UTC'?' UTC':' ICT');\n}\nfunction timezoneCaption(){return state.zone==='UTC'?'UTC':'ICT (UTC+7)'}\nfunction renderClock(){$('clock').textContent=formatStamp(Date.now())}\nfunction selectTimezone(zone){\n state.zone=zone==='UTC'?'UTC':'VN';\n $('timezoneSelect').value=state.zone;\n document.querySelectorAll('.tzlabel').forEach(el=>el.textContent=timezoneCaption());\n try{localStorage.setItem('atlas.display_time_zone',state.zone)}catch(e){}\n renderClock();\n // All presentation layers are refreshed; backend storage, OHLC bar times and\n // risk/TP/SL evaluation remain UTC and are never mutated by this selection.\n loadMarket();loadDashboard();loadResearch();loadTracking();loadOutcomeMetrics();\n loadMacro();loadMacroCalendar();loadWatchdog();\n}\nfunction age(t){return t?Math.max(0,Math.floor((Date.now()-new Date(t).getTime())/60000))+'m ago':'n/a'}\nasync function get(url){var r=await fetch(url,{cache:'no-store'});var j=await r.json();if(!r.ok)throw Error(j.error||'API '+r.status);return j}\nfunction indicator(ok,message){$('indicator').className='live'+(ok?'':' warn');$('indicatorText').textContent=message}\nasync function loadMarket(){try{var x=await get('/api/market');state.markets=x.items||[];$('count').textContent=fmt(state.markets.length);$('markettime').textContent=(x.mode==='live-on-request'?'Latest exchange response':'Cached snapshot')+' · '+formatStamp(x.updatedAt);renderMarkets();if(x.warning){indicator(false,'Using cached data');$('systemNotice').textContent=x.warning+' · Last source update: '+formatStamp(x.updatedAt)}else indicator(true,'Market API connected')}catch(e){indicator(false,'Market API unavailable');$('markettime').textContent=e.message;$('systemNotice').textContent='Market API unavailable: '+e.message;renderMarkets()}}\nfunction renderMarkets(){var q=$('search').value.toUpperCase(),f=$('direction').value;var arr=state.markets.filter(x=>(!q||x.symbol.includes(q))&&(f==='all'||(f==='up'?x.changePct>0:x.changePct<0))).slice(0,200);$('marketrows').innerHTML=arr.length?arr.map(x=>'<tr data-symbol=\"'+esc(x.symbol)+'\"><td class=\"sym\">'+esc(x.symbol.replace('_USDT',''))+' <span class=\"muted\">/ USDT</span></td><td>'+price(x.price)+'</td><td class=\"'+(x.changePct>=0?'up':'down')+'\">'+(x.changePct>=0?'+':'')+fmt(x.changePct,2)+'%</td><td>'+fmt(x.turnover)+'</td><td>'+fmt(Number(x.funding)*100,4)+'%</td></tr>').join(''):'<tr><td colspan=\"5\" class=\"empty\">No matching instruments or the exchange is unavailable.</td></tr>';$('marketrows').querySelectorAll('tr[data-symbol]').forEach(r=>r.onclick=function(){state.symbol=r.dataset.symbol;loadChart()})}\nasync function loadDashboard(){try{var x=await get('/api/dashboard');state.dashboard=x;var c=x.scanner?.counts||{};$('ready').textContent=fmt(c.ENTRY_READY);$('developing').textContent=fmt((c.NEAR_ENTRY||0)+(c.DEVELOPING||0));$('lastscan').textContent=formatStamp(x.scanner?.updatedAt);$('syncAge').textContent=x.scanner?'Scanner '+age(x.scanner.updatedAt):'No scanner snapshot yet';$('samples').textContent=fmt(x.calibration?.closedSamples);$('winrate').textContent=x.calibration?.baselineWinRate!=null?fmt(x.calibration.baselineWinRate*100,2)+'%':'—';['ENTRY_READY','NEAR_ENTRY','DEVELOPING','WATCHLIST'].forEach((k,i)=>$('b'+(i+1)).textContent=fmt(c[k]||0));var h=x.health;$('serviceHealth').innerHTML='Scheduled sync: <b>'+esc(h?.last_attempt_at?formatStamp(h.last_attempt_at):'Not yet run')+'</b><br>Last partial/full success: '+esc(formatStamp(h?.last_success_at))+'<br>Sources: '+esc(h?.synced_sources||'none')+'<br>Latest error: '+esc(h?.last_error||'none');renderSignals();}catch(e){$('systemNotice').textContent='Scanner backend: '+e.message}}\nfunction renderSignals(){var r=state.dashboard?.signals||[];$('signalrows').innerHTML=r.length?r.map(x=>'<tr><td class=\"sym\">'+esc(x.symbol)+'</td><td class=\"'+(x.direction==='LONG'?'up':'down')+'\">'+esc(x.direction)+'</td><td><span class=\"tag '+(x.bucket==='ENTRY_READY'?'ready':x.bucket==='DEVELOPING'?'dev':'')+'\">'+esc(x.bucket)+'</span></td><td>'+((x.entry_low!=null&&x.entry_high!=null)?fmt(x.entry_low,5)+' – '+fmt(x.entry_high,5):'—')+'</td><td>'+esc(formatStamp(x.source_updated_at))+'</td></tr>').join(''):'<tr><td colspan=\"5\" class=\"empty\">No published scanner alert signatures yet.</td></tr>'}\nfunction draw(rows){var canvas=$('chart'),dpr=window.devicePixelRatio||1,w=canvas.clientWidth,h=canvas.clientHeight;canvas.width=Math.max(1,w*dpr);canvas.height=Math.max(1,h*dpr);var ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);ctx.fillStyle='#101726';ctx.fillRect(0,0,w,h);if(!rows.length){ctx.fillStyle='#8fa2c0';ctx.font='13px system-ui';ctx.fillText('Candles unavailable from exchange',15,35);return}var lo=Math.min.apply(null,rows.map(x=>x.l)),hi=Math.max.apply(null,rows.map(x=>x.h));var range=Math.max(hi-lo,hi*.002);lo-=range*.07;hi+=range*.07;var padx=9,pady=14,cw=(w-2*padx)/rows.length;function y(v){return pady+(hi-v)/(hi-lo)*(h-pady*2)}ctx.strokeStyle='#263349';ctx.lineWidth=.7;for(var g=1;g<5;g++){var yy=(h/5)*g;ctx.beginPath();ctx.moveTo(0,yy);ctx.lineTo(w,yy);ctx.stroke()}rows.forEach(function(c,i){var x=padx+i*cw+cw/2,up=c.c>=c.o;ctx.strokeStyle=up?'#2ad49f':'#ee6581';ctx.fillStyle=ctx.strokeStyle;ctx.beginPath();ctx.moveTo(x,y(c.h));ctx.lineTo(x,y(c.l));ctx.stroke();ctx.fillRect(x-Math.max(1,cw*.27),Math.min(y(c.o),y(c.c)),Math.max(1.3,cw*.54),Math.max(1,Math.abs(y(c.o)-y(c.c))))});ctx.fillStyle='#91a3bf';ctx.font='11px system-ui';ctx.fillText(price(hi),10,12);ctx.fillText(price(lo),10,h-5)}\nasync function loadChart(){$('chartsymbol').textContent=state.symbol;$('chartstatus').textContent='Loading';try{var x=await get('/api/chart?symbol='+encodeURIComponent(state.symbol)+'&tf='+state.tf);draw(x.candles||[]);$('chartstatus').textContent=x.candles.length+' closed candles';$('chartnote').textContent=state.tf.toUpperCase()+' · '+esc(state.symbol)+' · closed-candle price action'}catch(e){draw([]);$('chartstatus').textContent='Unavailable';$('chartnote').textContent=e.message}}\nasync function loadResearch(){try{var x=await get(\"/api/research\"),r=x.signals||[];var times=(x.sources||[]).map(s=>s.source+\": \"+formatStamp(s.updated_at)).join(\" | \");$(\"researchStatus\").textContent=r.length+\" historical records\";$(\"researchRows\").innerHTML=r.length?r.map(s=>{var stale=!s.recorded_at||(Date.now()-Date.parse(s.recorded_at)>24*3600000);return \"<tr><td>\"+esc(s.source)+\" <span class=muted>\"+esc(s.model)+\"</span></td><td class=sym>\"+esc(s.symbol)+\"</td><td class=\"+(s.direction===\"LONG\"?\"up\":\"down\")+\">\"+esc(s.direction)+\"</td><td><span class=tag>\"+esc(s.outcome_status||s.outcome||\"NOT_RECORDED\")+(stale?\" · HISTORICAL\":\"\")+\"</span></td><td>\"+price(s.entry)+\"</td><td class=\"+(s.net_r>=0?\"up\":\"down\")+\">\"+(s.net_r==null?\"—\":fmt(s.net_r,3)+\"R\")+\"</td><td>\"+esc(formatStamp(s.recorded_at))+\"</td></tr>\"}).join(\"\"):\"<tr><td colspan=7 class=empty>No research records imported yet. Hourly scheduled import is enabled.</td></tr>\";}catch(e){$(\"researchStatus\").textContent=e.message}}\n\nvar liveWS=null,liveReconnect=0,lastPushAt=null;\n\nasync function loadWatchdog(){\n try{\n  const d=await get('/api/watchdog'),w=d.watchdog||{},st=w.status||'INITIALIZING',minutes=w.scanner_age_seconds==null?'unknown':Math.max(0,Math.round(w.scanner_age_seconds/60))+' min';\n  $('watchdogHealth').textContent='Scanner: '+st+' | Age: '+minutes+' | Last checked: '+formatStamp(w.checked_at)+\n   ' | GitHub recovery: '+(w.direct_recovery_configured?'configured':'missing token; GitHub watchdog fallback')+\n   ' | Telegram: '+(w.direct_telegram_configured?'Cloudflare direct':'GitHub OIDC relay')+\n   ' | Latest action: '+(w.note||'n/a')+\n   (w.last_dispatch_status?' | Dispatch: '+w.last_dispatch_status:'')+\n   (w.last_dispatch_error?' | Error: '+w.last_dispatch_error:'');\n  if(st==='STALE'){\n    $('lastscan').classList.add('down');$('syncAge').textContent='SCANNER STALE · '+minutes+' since latest source scan';\n  }else{$('lastscan').classList.remove('down');}\n }catch(e){$('watchdogHealth').textContent='Watchdog API unavailable: '+e.message}\n}\n\nasync function loadOutcomeMetrics(){\n try{\n  const x=await get('/api/outcomes'),b=x.bySource||[],total=b.reduce((a,v)=>a+v.total,0),w=b.reduce((a,v)=>a+(v.tp1_first||0),0),l=b.reduce((a,v)=>a+(v.sl_first||0),0);\n  $('pubcount').textContent=fmt(x.publications?.total||0);\n  $('moncount').textContent=fmt(total);\n  $('resolved').textContent=w+' / '+l;\n  $('outcomeRate').textContent=w+l?fmt(w*100/(w+l),1)+'%':'—';\n  const h=x.health||{};\n  $('outcomeHealthNote').textContent='Closed-candle outcome scan: '+(h.last_success_at?'last success '+formatStamp(h.last_success_at):'not yet verified')+' | evaluated '+(h.evaluated_count||0)+' | pending '+(h.pending_count||0)+(h.last_error?' | ERROR '+h.last_error:'')+'. TP1-first is a price-level benchmark, NOT realized returns.';\n }catch(e){$('outcomeHealthNote').textContent='Outcome metrics temporarily unavailable: '+e.message}\n}\n\nasync function loadTracking(){\n try{\n  const d=await get('/api/tracking'),signals=d.signals||[],events=d.events||[],pubs=d.publications||[];\n  $('liveTrackerSummary').textContent=signals.length+' monitored setups · observed prices only';\n  $('eventsummary').textContent=events.length+' most recent events';\n  $('pubsummary').textContent=pubs.length+' most recent confirmed publications';\n  $('pubrows').innerHTML=pubs.length?pubs.map(p=>'<tr><td>'+esc(formatStamp(p.sent_at))+'</td><td class=\"sym\">'+esc(p.symbol)+'</td><td>'+esc(p.direction)+'</td><td>'+esc(p.bucket)+'</td><td><span class=\"tag\">'+(p.is_trackable?'VALIDATED · TRACKING':'REFERENCE ONLY')+'</span></td></tr>').join(''):'<tr><td colspan=\"5\" class=\"empty\">No verified send receipts yet; historical state snapshots are not counted as confirmed Telegram deliveries.</td></tr>';\n  $('trackerows').innerHTML=signals.length?signals.map(s=>'<tr data-chart=\"'+esc(s.symbol)+'\"><td class=\"sym\">'+esc(s.symbol)+'</td><td class=\"'+(s.direction==='LONG'?'up':'down')+'\">'+esc(s.direction)+' · '+fmt(s.score,0)+'</td><td><span class=\"tag '+(s.status==='ENTRY_OBSERVED'?'ready':'')+'\">'+esc(s.status)+'</span></td><td>'+price(s.entry_low)+' – '+price(s.entry_high)+'</td><td>'+price(s.stop)+'</td><td>'+price(s.tp1)+(s.tp2==null?'':' / '+price(s.tp2))+'</td><td>'+price(s.last_price)+'</td><td>'+esc(formatStamp(s.last_tick_at))+'</td></tr>').join(''):'<tr><td colspan=\"8\" class=\"empty\">No new verified scanner plans yet. Historical alert signatures do not automatically create simulated trades.</td></tr>';\n  $('trackerows').querySelectorAll('tr[data-chart]').forEach(r=>r.onclick=()=>{state.symbol=r.dataset.chart;tab('market');loadChart()});\n  $('eventrows').innerHTML=events.length?events.map(e=>'<tr><td><span class=\"tag\">'+esc(e.kind)+'</span></td><td class=\"sym\">'+esc(e.symbol)+'</td><td>'+price(e.observed_price)+'</td><td>'+esc(formatStamp(e.observed_at))+'</td><td>'+esc(e.delivery_status)+'</td></tr>').join(''):'<tr><td colspan=\"5\" class=\"empty\">No confirmed price observations yet.</td></tr>';\n }catch(e){$('liveTrackerSummary').textContent='Tracking API unavailable: '+e.message}\n}\nfunction connectLive(){\n if(liveWS&&[0,1].includes(liveWS.readyState))return;\n const protocol=location.protocol==='https:'?'wss://':'ws://';\n try{\n  liveWS=new WebSocket(protocol+location.host+'/api/ws');\n  liveWS.onopen=function(){liveReconnect=0;indicator(true,'WebSocket connected · snapshot feed');$('markettime').textContent='Server push · MEXC REST market snapshots (~10s)'};\n  liveWS.onmessage=function(e){\n   if(e.data==='pong')return;\n   let x;try{x=JSON.parse(e.data)}catch{return}\n   if(x.type==='market'&&Array.isArray(x.items)){\n    lastPushAt=Date.now();state.markets=x.items;$('count').textContent=fmt(x.items.length);\n    $('markettime').textContent='WebSocket push · '+formatStamp(x.updatedAt)+' · '+x.mode;\n    indicator(true,'Live push · '+x.items.length+' instruments');\n    renderMarkets();\n   }\n   if(x.type==='tracking'){loadTracking()}\n   if(x.type==='error'){indicator(false,'Upstream degraded · cached data')}\n  };\n  liveWS.onclose=function(){indicator(false,'Reconnecting live stream...');const delay=Math.min(30000,1000*Math.pow(2,Math.min(liveReconnect++,5)));setTimeout(connectLive,delay)};\n  liveWS.onerror=function(){try{liveWS.close()}catch{}};\n }catch(e){indicator(false,'WebSocket unavailable · HTTP fallback');setTimeout(connectLive,10000)}\n}\n\n\nlet macroCache={news:[],signalContext:[],feeds:[],health:null,updatedAt:null};\nfunction renderMacro(){\n const d=macroCache;\n const search=String($('macroSearch')?.value||'').trim().toLowerCase();\n const impact=$('macroImpactFilter')?.value||'';\n const news=(d.news||[]).filter(n=>(!impact||n.impact===impact)&&(!search||(n.title+' '+n.summary_vi+' '+n.source_name+' '+n.category).toLowerCase().includes(search)));\n $('macroCount').textContent=fmt((d.news||[]).length);\n $('macroHigh').textContent=fmt((d.news||[]).filter(n=>n.impact==='HIGH').length);\n $('macroReactions').textContent=fmt((d.news||[]).reduce((a,n)=>a+(n.reactions||[]).length,0));\n $('macroSources').textContent=(d.health?.source_success??'—')+'/'+(d.health?.source_total??9);\n $('macroStatus').textContent=d.updatedAt?'Last checked '+formatStamp(d.updatedAt):'No successful collector run yet';\n const chip=(text,kind='')=>'<span class=\"macro-tag '+kind+'\">'+esc(text)+'</span>';\n $('macroNews').innerHTML=news.length?news.map(n=>{\n  const reactions=n.reactions||[];\n  const formatReaction=(asset,h)=>{\n   const x=reactions.find(r=>r.symbol===asset&&r.horizon===h);\n   return '<div class=\"macro-asset\">'+esc(asset.replace('_USDT',''))+' · '+esc(h)+'<div><strong class=\"'+(x?.change_pct>=0?'macro-up':'macro-down')+'\">'+(x?((x.change_pct>=0?'+':'')+fmt(x.change_pct,2)+'%'):'Awaiting')+'</strong></div></div>';\n  };\n  const link=String(n.source_url||'').startsWith('https://')?n.source_url:'#';\n  return '<article class=\"macro-card\"><div class=\"macro-top\"><span class=\"macro-kicker\">'+esc(n.source_name)+' · '+esc(formatStamp(n.published_at))+'</span>'+chip(n.impact,n.impact==='HIGH'?'high':n.impact==='MEDIUM'?'medium':'')+'</div>'+\n   '<div class=\"macro-title\">'+esc(n.title)+'</div><div class=\"macro-tags\">'+chip(n.category)+chip(n.tier==='official'?'Official source':'Aggregator · unverified secondary')+chip(n.summary_method==='workers_ai_headline_only'?'AI summary':'Rule-based summary')+chip(n.bias.replaceAll('_',' '))+'</div>'+\n   '<div class=\"macro-summary\">'+esc(n.summary_vi)+'</div><div class=\"macro-impact\"><b>Conditional crypto impact:</b> '+esc(n.rationale_vi)+'</div><div class=\"macro-reaction\">'+formatReaction('BTC_USDT','15m')+formatReaction('ETH_USDT','15m')+formatReaction('BTC_USDT','1h')+formatReaction('ETH_USDT','1h')+formatReaction('BTC_USDT','4h')+formatReaction('ETH_USDT','4h')+formatReaction('BTC_USDT','24h')+formatReaction('ETH_USDT','24h')+'</div>'+\n   '<a href=\"'+esc(link)+'\" target=\"_blank\" rel=\"noopener noreferrer\">Read original source ↗</a><span class=\"small\">Reactions are observed price changes; not causal proof. No actual-vs-forecast surprise data.</span></article>';\n }).join(''):'<div class=\"empty\">No matching sourced macro news yet. Check source freshness and filters.</div>';\n $('macroContextCount').textContent=(d.signalContext||[]).length+' associations';\n $('macroContextRows').innerHTML=(d.signalContext||[]).length?d.signalContext.map(p=>'<tr><td class=\"sym\">'+esc(p.symbol)+' '+esc(p.direction)+'</td><td>'+esc(formatStamp(p.sent_at))+'</td><td>'+esc(p.title)+'</td><td><span class=\"tag\">'+esc(p.relation.replaceAll('_',' '))+'</span></td></tr>').join(''):'<tr><td colspan=\"4\" class=\"empty\">No verified high-impact overlap between source news and confirmed signal receipts yet.</td></tr>';\n $('macroFeeds').innerHTML=(d.feeds||[]).length?d.feeds.map(f=>'<tr><td>'+esc(f.source_name)+'</td><td>'+esc(f.tier)+'</td><td>'+esc(formatStamp(f.last_success_at))+'</td><td>'+fmt(f.new_count||0)+'</td><td>'+esc(f.last_error||'OK')+'</td></tr>').join(''):'<tr><td colspan=\"5\" class=\"empty\">Collector not yet initialized. Data is not fabricated.</td></tr>';\n}\nasync function loadMacroCalendar(){\n try{\n  const x=await get('/api/macro/calendar'),items=x.events||[],h=x.health||{};\n  const when=e=>{\n   const d=new Date(e.scheduled_at);\n   if(!Number.isFinite(d.getTime()))return 'unknown time';\n   return esc(formatStamp(e.scheduled_at));\n  };\n  $('macroCalendarStatus').textContent=h.last_success_at?'BLS last updated '+formatStamp(h.last_success_at)+(h.last_error?' · Source error: '+h.last_error:''):'No verified calendar sync yet'+(h.last_error?' · '+h.last_error:'');\n  $('macroCalendarRows').innerHTML=items.length?items.map(e=>'<tr><td>'+when(e)+'</td><td>'+esc(e.title)+'</td><td><span class=\"tag\">'+esc(e.impact)+'</span></td><td><a href=\"'+esc(e.source_url)+'\" target=\"_blank\" rel=\"noopener noreferrer\">BLS calendar</a></td></tr>').join(''):'<tr><td colspan=\"4\" class=\"empty\">No verified upcoming BLS events available; check feed health.</td></tr>';\n }catch(e){$('macroCalendarStatus').textContent='Calendar API unavailable: '+e.message}\n}\n\nasync function loadMacro(){\n try{const d=await get('/api/macro?limit=80');macroCache=d;renderMacro()}\n catch(e){$('macroStatus').textContent='Macro API unavailable: '+e.message}\n}\n\nfunction tab(t){state.tab=t;['market','signals','tracking','macro','research','analytics'].forEach(k=>{$(k+'Tab').classList.toggle('hide',k!==t)});document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));$('heading').textContent={market:'Market Intelligence Overview',signals:'Strategy Signal Feed',tracking:'Live Signal Tracking',macro:'Macro & News Intelligence',research:'Research Journal',analytics:'Performance & System Health'}[t];if(t==='analytics')$('analyticsBox').style.display='grid';if(t==='tracking'){loadTracking();loadOutcomeMetrics()}if(t==='macro'){loadMacro();loadMacroCalendar()}}\n$('macroImpactFilter').onchange=renderMacro;$('macroSearch').oninput=renderMacro;$('macroRefresh').onclick=loadMacro;document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>tab(b.dataset.tab));$('search').oninput=renderMarkets;$('direction').onchange=renderMarkets;$('tf15').onclick=()=>{state.tf='15m';$('tf15').className='active';$('tf1h').className='';loadChart()};$('tf1h').onclick=()=>{state.tf='1h';$('tf1h').className='active';$('tf15').className='';loadChart()};var savedZone=null;try{savedZone=localStorage.getItem('atlas.display_time_zone')}catch(e){}if(savedZone==='UTC')state.zone='UTC';$('timezoneSelect').value=state.zone;document.querySelectorAll('.tzlabel').forEach(el=>el.textContent=timezoneCaption());$('timezoneSelect').onchange=()=>selectTimezone($('timezoneSelect').value);renderClock();setInterval(renderClock,1000);loadMarket();loadDashboard();loadWatchdog();loadMacro();loadMacroCalendar();loadChart();loadResearch();loadTracking();loadOutcomeMetrics();connectLive();setInterval(()=>{if(!liveWS||liveWS.readyState!==1||(lastPushAt&&Date.now()-lastPushAt>45000))loadMarket()},15000);setInterval(loadDashboard,60000);setInterval(loadWatchdog,60000);setInterval(loadResearch,600000);setInterval(loadTracking,60000);setInterval(loadOutcomeMetrics,60000);setInterval(loadMacro,60000);setInterval(loadMacroCalendar,300000);setInterval(()=>{if(state.tab==='market')loadChart()},60000);\n</script></body></html>";
